import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CnqZ57Z3.js";const o="/flutter-tutorial-site/assets/EP.01-dart-basics.B1lO7HBX.svg",g=JSON.parse('{"title":"EP.01 问号满天飞 · Dart 语法基础","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.01-dart-basics.md","filePath":"comics/EP.01-dart-basics.md","lastUpdated":1792660454000}'),d={name:"comics/EP.01-dart-basics.md"};function n(c,e,l,r,h,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="ep-01-问号满天飞-·-dart-语法基础" tabindex="-1">EP.01 问号满天飞 · Dart 语法基础 <a class="header-anchor" href="#ep-01-问号满天飞-·-dart-语法基础" aria-label="Permalink to &quot;EP.01 问号满天飞 · Dart 语法基础&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/stage-1/01-dart-basics">阶段一 · Dart 语法基础</a></p></blockquote><img src="'+o+`" alt="EP.01 问号满天飞 · var / final / const"><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><p>达达第一次翻开 Flutter 代码，被 <code>String? name</code> 里的问号和 <code>required</code> 关键字整懵了；小薇也跟着吐槽装环境时从没见过这些。帧叔出场，用「声明三板斧」讲清 <code>var</code> / <code>final</code> / <code>const</code> 的分工，并用 <code>const DateTime.now()</code> 的翻车现场说明了编译期常量与运行期值的边界。最后帧叔点题：<strong>类型不是枷锁，是护栏</strong>。</p><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="格-1-·-困境-问号满天飞" tabindex="-1">格 1 · 困境：问号满天飞 <a class="header-anchor" href="#格-1-·-困境-问号满天飞" aria-label="Permalink to &quot;格 1 · 困境：问号满天飞&quot;">​</a></h3><p>初学 Dart 最先撞见的两个陌生符号：</p><ul><li><code>String?</code> —— 可空类型标记。Dart 开启空安全后，变量默认<strong>不可为 null</strong>，只有显式加 <code>?</code> 才允许为空。</li><li><code>required</code> —— 命名参数的必传标记。Flutter Widget 的构造函数大量出现，如 <code>required this.title</code>。</li></ul><p>这两个符号不是装饰，而是<strong>编译器强制执行的契约</strong>：可空变量不判空就用，编译直接报错；<code>required</code> 参数不传，同样编译报错。</p><h3 id="格-2-·-揭秘-声明三板斧" tabindex="-1">格 2 · 揭秘：声明三板斧 <a class="header-anchor" href="#格-2-·-揭秘-声明三板斧" aria-label="Permalink to &quot;格 2 · 揭秘：声明三板斧&quot;">​</a></h3><table tabindex="0"><thead><tr><th>声明</th><th>赋值时机</th><th>能否改</th><th>典型场景</th></tr></thead><tbody><tr><td><code>var</code></td><td>声明时</td><td>可以</td><td>普通局部变量</td></tr><tr><td><code>final</code></td><td>运行期，仅一次</td><td>不可改</td><td>网络请求结果、当前时间</td></tr><tr><td><code>const</code></td><td>编译期</td><td>不可改</td><td>数学常量、写死的配置</td></tr></tbody></table><p>配套技能：</p><ul><li><strong>空合并 <code>??</code></strong>：<code>nick ?? &#39;暂无&#39;</code>——左边为 <code>null</code> 时取右边的兜底值。</li><li><strong>空安全调用 <code>?.</code></strong>：<code>user?.name</code>——对象为 <code>null</code> 时整个表达式返回 <code>null</code>，不崩溃。</li></ul><h3 id="格-3-·-实证-const-翻车现场" tabindex="-1">格 3 · 实证：const 翻车现场 <a class="header-anchor" href="#格-3-·-实证-const-翻车现场" aria-label="Permalink to &quot;格 3 · 实证：const 翻车现场&quot;">​</a></h3><div class="language-dart vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dart</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> now </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> DateTime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">now</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 编译错误</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">final</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> now </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> DateTime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">now</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 正确</span></span></code></pre></div><p><code>const</code> 要求值在<strong>编译期</strong>就确定，而 <code>DateTime.now()</code> 要等到<strong>运行期</strong>才能算出来，所以编译器拒绝。判断口诀：<strong>这个值是写代码时就知道，还是跑起来才知道？</strong> 前者才能 <code>const</code>。</p><h3 id="格-4-·-结案-类型是护栏" tabindex="-1">格 4 · 结案：类型是护栏 <a class="header-anchor" href="#格-4-·-结案-类型是护栏" aria-label="Permalink to &quot;格 4 · 结案：类型是护栏&quot;">​</a></h3><p>最佳实践三条：</p><ol><li>能 <code>final</code> 不 <code>var</code>，能 <code>const</code> 不 <code>final</code>——越严格的声明，编译器能帮你拦下的错误越多；</li><li>Widget 构造参数优先用命名参数 <code>{ }</code>，调用处自解释；</li><li>运行期的值别用 <code>const</code> 接。</li></ol><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">本话坑点</p><ol><li><strong><code>[ ]</code> 与 <code>{ }</code> 混用</strong>：<code>[int b = 0]</code> 是可选位置参数，<code>{int b = 0}</code> 是命名参数，传参方式完全不同，混用直接编译报错。</li><li><strong>可空变量未判空就使用</strong>：<code>String? name; print(name.length)</code> 编译不通过，改用 <code>name?.length</code> 或 <code>if (name != null)</code> 判空。</li><li><strong>对 <code>final</code> 变量二次赋值</strong>：<code>final</code> 不是「暂时不变」，是「永远只能赋一次」，编译期就会拦下。</li></ol></div><h2 id="自测-3-题" tabindex="-1">自测 3 题 <a class="header-anchor" href="#自测-3-题" aria-label="Permalink to &quot;自测 3 题&quot;">​</a></h2><p><strong>Q1</strong>：<code>const pi = 3.14159</code> 和 <code>final pi = 3.14159</code> 都能编译通过，二者区别是什么？</p><details class="details custom-block"><summary>查看答案</summary><p><code>const</code> 是编译期常量，内存中只有一份，且可嵌套进 <code>const</code> 构造；<code>final</code> 是运行期赋值一次。对字面量而言行为接近，但习惯上写死的字面量用 <code>const</code>，让编译器做更多优化。</p></details><p><strong>Q2</strong>：下面代码为什么不通过编译？怎么改？</p><div class="language-dart vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dart</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> nickname;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nickname.length);</span></span></code></pre></div><details class="details custom-block"><summary>查看答案</summary><p><code>nickname</code> 是可空类型，直接访问 <code>.length</code> 可能空指针，空安全下编译器拒绝。改法：<code>print(nickname?.length ?? 0)</code>，或先 <code>if (nickname != null)</code> 判空。</p></details><p><strong>Q3</strong>：<code>const now = DateTime.now()</code> 为什么报错？应该用什么？</p><details class="details custom-block"><summary>查看答案</summary><p><code>DateTime.now()</code> 是运行期才能确定的值，不满足 <code>const</code> 的编译期常量要求。应改用 <code>final now = DateTime.now()</code>。</p></details><hr><p>下一话：<a href="./EP.02-env-setup">EP.02 doctor 全绿行动 · 开发环境搭建</a></p>`,32)])])}const u=a(d,[["render",n]]);export{g as __pageData,u as default};
